  children: [
    jsx_runtime.jsx(Plain, {}),
    jsx_runtime.jsx(_Underscore, {})   // identifier
  ]
});
Per JSX semantics, only a name starting with a lowercase letter is a host element; _Underscore is a valid component reference.

What do you see instead?
With --react-compiler, the underscore-prefixed name becomes a string:

var App = () => {
  let $ = react_compiler_runtime.c(1);
  let t0;
  if ($[0] === __MEMO_CACHE_SENTINEL)
    t0 = jsx_runtime.jsxs("p", {
      children: [
